insert into public.lessons (id, phase_id, position, label, title, description, heading, subtitle)
insert into public.lesson_sections (lesson_id, position, type, score_key, title, time_label, hint, body, short_input) values
  ('6.1.1', 1, 'mcq', 'P', $q$Phát âm$q$, '3 phút', $q$Chọn từ có phần gạch chân phát âm khác các từ còn lại.$q$, null, false),
  ('6.1.1', 2, 'mcq', 'R', 'Đọc hiểu — True / False', '5 phút', 'Đọc đoạn văn rồi chọn True (đúng) hoặc False (sai).', $q$<p>My name is Lan. I am in grade 6 at Hoa Binh Secondary School. It is a big school with a large library and a computer room. I wear a uniform every day.</p><p>My school starts at seven o'clock. I usually ride my bike to school with my best friend, Mai. We have Maths, English and Science on Mondays. My favourite subject is English because the teacher is very friendly.</p><p>Today is Sunday, so I am not at school. I am doing my homework and my brother is playing football in the garden.</p>$q$, false),
  ('6.1.1', 3, 'mcq', 'C', 'Điền vào đoạn văn', '5 phút', 'Đọc đoạn văn và chọn từ đúng cho mỗi chỗ trống (1)–(5).', $q$<p>Hi, I'm Nam. This is my new school. It <b>(1)</b> ________ in the countryside. There are 500 students and 30 teachers.</p><p>Every morning, I <b>(2)</b> ________ breakfast at six o'clock and then go to school. At break time, my friends and I often <b>(3)</b> ________ football in the schoolyard. Look! My classmates <b>(4)</b> ________ in the library now. They are reading books. I love my school <b>(5)</b> ________ the teachers are kind.</p>$q$, false),
  ('6.1.1', 4, 'match', 'N', 'Nối', '4 phút', $q$Nối câu hỏi với câu trả lời phù hợp.$q$, null, false),
  ('6.1.1', 5, 'error', 'E', 'Tìm lỗi sai', '4 phút', 'Chọn phần gạch chân A, B, C hoặc D bị sai trong mỗi câu.', null, false),
  ('6.1.1', 6, 'typed', 'W', 'Dạng đúng của từ', '4 phút', 'Viết dạng đúng của từ trong ngoặc. Chỉ gõ từ cần điền.', null, true),
  ('6.1.1', 7, 'typed', 'T', 'Viết lại câu', '5 phút', 'Viết lại cả câu sao cho nghĩa không đổi, bắt đầu bằng phần cho sẵn.', null, false);
