  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 1), 2, $q$Chọn từ có phần gạch chân phát âm khác.$q$, null, array[$q$sm[a]rt$q$, $q$cl[a]ss$q$, $q$h[a]lf$q$, $q$h[a]ppy$q$]::text[], 4, null, $q$h<u>a</u>ppy đọc /æ/; các từ còn lại đọc /ɑː/.$q$, $q$/ɑː/$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 1), 3, $q$Chọn từ có phần gạch chân phát âm khác.$q$, null, array[$q$M[o]nday$q$, $q$m[o]ther$q$, $q$h[o]me$q$, $q$c[o]me$q$]::text[], 3, null, $q$h<u>o</u>me đọc /əʊ/; các từ còn lại đọc /ʌ/.$q$, $q$/ʌ/$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 1), 4, $q$Chọn từ có phần gạch chân phát âm khác.$q$, null, array[$q$book[s]$q$, $q$pencil[s]$q$, $q$ruler[s]$q$, $q$bag[s]$q$]::text[], 1, null, $q$book<u>s</u> đọc /s/ (sau âm /k/); các từ còn lại đọc /z/.$q$, $q$đuôi -s$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 2), 1, $q$Lan's school has a large library.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 1, null, $q$"It is a big school with a large library…"$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 2), 2, $q$Lan walks to school every day.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 2, null, $q$Lan thường <b>đạp xe</b> đến trường: "I usually ride my bike to school".$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 2), 3, $q$Lan likes English because of her teacher.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 1, null, $q$"…because the teacher is very friendly."$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 2), 4, $q$Lan is at school today.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 2, null, $q$Hôm nay là Chủ nhật: "I am not at school".$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 3), 1, '(1)', null, array[$q$is$q$, $q$are$q$, $q$am$q$, $q$be$q$]::text[], 1, null, $q$Chủ ngữ <b>It</b> (số ít) → <b>is</b>.$q$, $q$to be$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 3), 2, '(2)', null, array[$q$do$q$, $q$have$q$, $q$play$q$, $q$study$q$]::text[], 2, null, $q$Cụm cố định: <b>have breakfast</b>.$q$, $q$collocation$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 3), 3, '(3)', null, array[$q$play$q$, $q$do$q$, $q$have$q$, $q$study$q$]::text[], 1, null, $q$<b>play football</b>; "often" → hiện tại đơn, chủ ngữ số nhiều giữ nguyên động từ.$q$, $q$present simple$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 3), 4, '(4)', null, array[$q$study$q$, $q$studies$q$, $q$are studying$q$, $q$is studying$q$]::text[], 3, null, $q$"Look! … now" → hiện tại tiếp diễn; <b>My classmates</b> số nhiều → <b>are studying</b>.$q$, $q$present continuous$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 3), 5, '(5)', null, array[$q$but$q$, $q$because$q$, $q$so$q$, $q$or$q$]::text[], 2, null, $q$Vế sau nêu lý do → <b>because</b>.$q$, $q$liên từ$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 4), 1, $q$What time does your school start?$q$, $q$It starts at seven o'clock.$q$, null, null, null, $q$Hỏi giờ (What time) → trả lời bằng giờ.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 4), 2, $q$How do you go to school?$q$, $q$I usually go by bike.$q$, null, null, null, $q$Hỏi phương tiện (How) → by bike.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 4), 3, $q$What's your favourite subject?$q$, $q$It's English.$q$, null, null, null, $q$Hỏi môn học yêu thích.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 4), 4, $q$What are you doing now?$q$, $q$I'm doing my homework.$q$, null, null, null, $q$Câu hỏi tiếp diễn → trả lời tiếp diễn.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 4), 5, $q$Who is your form teacher?$q$, $q$Mrs Hoa is.$q$, null, null, null, $q$Hỏi người (Who) → trả lời tên người.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 5), 1, null, null, array[$q$My brother$q$, $q$go$q$, $q$to school$q$, $q$by bus every day.$q$]::text[], 2, null, $q$go → <b>goes</b> (chủ ngữ số ít, hiện tại đơn).$q$, $q$present simple$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 5), 2, null, null, array[$q$Look!$q$, $q$The students$q$, $q$play$q$, $q$in the schoolyard.$q$]::text[], 3, null, $q$"Look!" → đang diễn ra: play → <b>are playing</b>.$q$, $q$present continuous$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 5), 3, null, null, array[$q$She$q$, $q$doesn't$q$, $q$has$q$, $q$a new compass.$q$]::text[], 3, null, $q$Sau <b>doesn't</b> dùng động từ nguyên mẫu: has → <b>have</b>.$q$, $q$present simple$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 5), 4, null, null, array[$q$Listen!$q$, $q$Somebody$q$, $q$is sing$q$, $q$in the music room.$q$]::text[], 3, null, $q$is sing → <b>is singing</b> (be + V-ing).$q$, $q$present continuous$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 6), 1, $q$My new school has a lot of ___ students. (FRIEND)$q$, null, null, null, array[$q$friendly$q$]::text[], $q$Trước danh từ <i>students</i> cần tính từ: friend → <b>friendly</b>.$q$, $q$word form$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 6), 2, $q$Mr Nam is a very good ___. He teaches us Maths. (TEACH)$q$, null, null, null, array[$q$teacher$q$]::text[], $q$Sau <i>a very good</i> cần danh từ chỉ người: <b>teacher</b>.$q$, $q$word form$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 6), 3, $q$There are many ___ activities at my school. (INTEREST)$q$, null, null, null, array[$q$interesting$q$]::text[], $q$Tính từ mô tả hoạt động: <b>interesting</b> (thú vị).$q$, $q$word form$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 6), 4, $q$I like ___ in the school club. (SWIM)$q$, null, null, null, array[$q$swimming$q$]::text[], $q$<b>like + V-ing</b>; swim → swimming (gấp đôi m).$q$, $q$V-ing$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 7), 1, $q$My school has a big library. → There …$q$, null, null, null, array[$q$There is a big library in my school$q$, $q$There's a big library in my school$q$, $q$There is a big library at my school$q$]::text[], $q$<b>have</b> → <b>There is</b> + danh từ số ít.$q$, $q$there is$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 7), 2, $q$Lan's favourite subject is English. → Lan likes …$q$, null, null, null, array[$q$Lan likes English best$q$, $q$Lan likes English most$q$, $q$Lan likes English the most$q$, $q$Lan likes English the best$q$]::text[], $q$favourite = like … best / most.$q$, $q$favourite$q$),
  ((select id from public.lesson_sections where lesson_id = '6.1.1' and position = 7), 3, $q$Nam goes to school on foot. → Nam walks …$q$, null, null, null, array[$q$Nam walks to school$q$]::text[], $q$go … on foot = <b>walk</b>; chủ ngữ số ít → walks.$q$, $q$present simple$q$);
insert into public.lessons (id, phase_id, position, label, title, description, heading, subtitle)
insert into public.lesson_sections (lesson_id, position, type, score_key, title, time_label, hint, body, short_input) values
  ('7.1.1', 1, 'mcq', 'P', $q$Phát âm$q$, '3 phút', $q$Chọn từ có phần gạch chân phát âm khác các từ còn lại.$q$, null, false),
  ('7.1.1', 2, 'mcq', 'R', 'Đọc hiểu — True / False', '5 phút', 'Đọc đoạn văn rồi chọn True (đúng) hoặc False (sai).', $q$<p>My name is Huy. I have an unusual hobby: I make models from used things. I started it two years ago when my father showed me how to make a small car from an old box.</p><p>Now I usually spend two hours on my hobby at weekends. I often use plastic bottles, paper and old cans. My hobby is not expensive and it is good for the environment.</p><p>My sister doesn't like making models. She enjoys gardening. She sometimes grows vegetables with our grandma.</p>$q$, false),
  ('7.1.1', 3, 'mcq', 'C', 'Điền vào đoạn văn', '5 phút', 'Đọc đoạn văn và chọn từ đúng cho mỗi chỗ trống (1)–(5).', $q$<p>Collecting stamps is my favourite hobby. I <b>(1)</b> ________ collecting them when I was eight. My uncle often <b>(2)</b> ________ me stamps from other countries.</p><p>I keep them <b>(3)</b> ________ albums. I think collecting stamps is <b>(4)</b> ________ because I can learn about the world. My friends don't share my hobby, but they enjoy <b>(5)</b> ________ my collection.</p>$q$, false),
  ('7.1.1', 4, 'match', 'N', 'Nối', '4 phút', $q$Nối mỗi sở thích với mô tả phù hợp.$q$, null, false),
  ('7.1.1', 5, 'error', 'E', 'Tìm lỗi sai', '4 phút', 'Chọn phần gạch chân A, B, C hoặc D bị sai trong mỗi câu.', null, false),
  ('7.1.1', 6, 'typed', 'W', 'Dạng đúng của từ', '4 phút', 'Viết dạng đúng của từ trong ngoặc. Chỉ gõ từ cần điền.', null, true),
  ('7.1.1', 7, 'typed', 'T', 'Viết lại câu', '5 phút', 'Viết lại cả câu sao cho nghĩa không đổi, bắt đầu bằng phần cho sẵn.', null, false);
