  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 1), 4, $q$Chọn từ có phần gạch chân phát âm khác.$q$, null, array[$q$hobbie[s]$q$, $q$collect[s]$q$, $q$play[s]$q$, $q$garden[s]$q$]::text[], 2, null, $q$collect<u>s</u> đọc /s/ (sau âm /t/); các từ còn lại đọc /z/.$q$, $q$đuôi -s$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 2), 1, $q$Huy's father taught him how to make models.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 1, null, $q$"…my father showed me how to make a small car from an old box."$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 2), 2, $q$Huy spends two hours on his hobby every day.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 2, null, $q$Huy dành 2 tiếng <b>vào cuối tuần</b>, không phải mỗi ngày.$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 2), 3, $q$Huy's hobby costs a lot of money.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 2, null, $q$"My hobby is not expensive…"$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 2), 4, $q$Huy's sister likes gardening.$q$, null, array[$q$True$q$, $q$False$q$]::text[], 1, null, $q$"She enjoys gardening."$q$, $q$đọc hiểu$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 3), 1, '(1)', null, array[$q$start$q$, $q$started$q$, $q$starting$q$, $q$starts$q$]::text[], 2, null, $q$"when I was eight" → quá khứ đơn: <b>started</b>.$q$, $q$past simple$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 3), 2, '(2)', null, array[$q$send$q$, $q$sends$q$, $q$sending$q$, $q$is send$q$]::text[], 2, null, $q$"often", chủ ngữ <i>My uncle</i> số ít → <b>sends</b>.$q$, $q$present simple$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 3), 3, '(3)', null, array[$q$at$q$, $q$on$q$, $q$in$q$, $q$to$q$]::text[], 3, null, $q$Để đồ <b>trong</b> album: <b>in</b> albums.$q$, $q$giới từ$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 3), 4, '(4)', null, array[$q$bored$q$, $q$boring$q$, $q$interested$q$, $q$interesting$q$]::text[], 4, null, $q$Mô tả sở thích (vật) gây hứng thú → <b>interesting</b>.$q$, $q$-ed / -ing$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 3), 5, '(5)', null, array[$q$look at$q$, $q$to look at$q$, $q$looking at$q$, $q$looks at$q$]::text[], 3, null, $q$<b>enjoy + V-ing</b> → looking at.$q$, $q$enjoy + V-ing$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 4), 1, $q$gardening$q$, $q$growing flowers and vegetables$q$, null, null, null, $q$garden = vườn → trồng hoa, rau.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 4), 2, $q$collecting dolls$q$, $q$keeping many dolls of different kinds$q$, null, null, null, $q$collect = sưu tầm.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 4), 3, $q$horse riding$q$, $q$sitting on a horse and controlling it$q$, null, null, null, $q$ride a horse = cưỡi ngựa.$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 4), 4, $q$making pottery$q$, $q$making pots and bowls from clay$q$, null, null, null, $q$pottery = đồ gốm, làm từ đất sét (clay).$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 4), 5, $q$ice-skating$q$, $q$moving on ice with special boots$q$, null, null, null, $q$skate = trượt (trên băng).$q$, 'vocabulary'),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 5), 1, null, null, array[$q$I$q$, $q$enjoy$q$, $q$watch$q$, $q$cartoons on TV.$q$]::text[], 3, null, $q$<b>enjoy + V-ing</b>: watch → <b>watching</b>.$q$, $q$enjoy + V-ing$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 5), 2, null, null, array[$q$My brother$q$, $q$never is$q$, $q$late$q$, $q$for school.$q$]::text[], 2, null, $q$Trạng từ tần suất đứng <b>sau</b> to be: <b>is never</b>.$q$, $q$adverb of frequency$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 5), 3, null, null, array[$q$Does$q$, $q$your sister$q$, $q$likes$q$, $q$cooking?$q$]::text[], 3, null, $q$Sau <b>Does</b> dùng động từ nguyên mẫu: likes → <b>like</b>.$q$, $q$present simple$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 5), 4, null, null, array[$q$She$q$, $q$doesn't mind$q$, $q$to do$q$, $q$the washing-up.$q$]::text[], 3, null, $q$<b>mind + V-ing</b>: to do → <b>doing</b>.$q$, $q$mind + V-ing$q$),
