  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 6), 2, $q$Gardening is a ___ hobby. It helps us relax. (RELAX)$q$, null, null, null, array[$q$relaxing$q$]::text[], $q$Tính từ mô tả sở thích gây thư giãn: <b>relaxing</b>.$q$, $q$-ed / -ing$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 6), 3, $q$Dancing is good for your ___. (HEALTHY)$q$, null, null, null, array[$q$health$q$]::text[], $q$Sau tính từ sở hữu <i>your</i> cần danh từ: <b>health</b>.$q$, $q$word form$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 6), 4, $q$My grandmother is a ___ gardener. (CARE)$q$, null, null, null, array[$q$careful$q$]::text[], $q$Trước danh từ <i>gardener</i> cần tính từ: <b>careful</b>.$q$, $q$word form$q$),
  ((select id from public.lesson_sections where lesson_id = '7.1.1' and position = 7), 1, $q$I like playing badminton. → I enjoy …$q$, null, null, null, array[$q$I enjoy playing badminton$q$]::text[], $q$like ≈ <b>enjoy + V-ing</b>.$q$, $q$enjoy + V-ing$q$),
