insert into public.lesson_sections (lesson_id, position, type, score_key, title, time_label, hint, body, short_input) values
  ('8.1.1', 1, 'mcq', 'P', $q$Phát âm$q$, '3 phút', $q$Chọn từ có phần gạch chân phát âm khác các từ còn lại.$q$, null, false),
  ('8.1.1', 2, 'mcq', 'R', 'Đọc hiểu — True / False', '5 phút', 'Đọc đoạn văn rồi chọn True (đúng) hoặc False (sai).', $q$<p>Many teenagers in Viet Nam spend their free time online. They love chatting with friends and watching videos. However, some parents worry that their children spend too much time on screens.</p><p>Last month, my school started a leisure club. Students can join activities such as DIY, board games and cooking. I joined the DIY group because I fancy making things with my hands. Last week, I made a bookshelf for my bedroom.</p><p>My friend Hoa prefers cooking. She has learnt to make spring rolls and she is very proud of it.</p>$q$, false),
  ('8.1.1', 3, 'mcq', 'C', 'Điền vào đoạn văn', '5 phút', 'Đọc đoạn văn và chọn từ đúng cho mỗi chỗ trống (1)–(5).', $q$<p>In my free time, I enjoy <b>(1)</b> ________ to music. I also love <b>(2)</b> ________ out with my friends at weekends. We usually go to the park and play <b>(3)</b> ________ games such as hide-and-seek.</p><p>My sister prefers staying at home. She is <b>(4)</b> ________ in doing puzzles. Our parents think it is important to have a good balance between study and <b>(5)</b> ________.</p>$q$, false),
  ('8.1.1', 4, 'match', 'N', 'Nối', '4 phút', $q$Nối mỗi từ với định nghĩa phù hợp.$q$, null, false),
  ('8.1.1', 5, 'error', 'E', 'Tìm lỗi sai', '4 phút', 'Chọn phần gạch chân A, B, C hoặc D bị sai trong mỗi câu.', null, false),
  ('8.1.1', 6, 'typed', 'W', 'Dạng đúng của từ', '4 phút', 'Viết dạng đúng của từ trong ngoặc. Chỉ gõ từ cần điền.', null, true),
  ('8.1.1', 7, 'typed', 'T', 'Viết lại câu', '5 phút', 'Viết lại cả câu sao cho nghĩa không đổi, bắt đầu bằng phần cho sẵn.', null, false);
