insert into public.lesson_sections (lesson_id, position, type, score_key, title, time_label, hint, body, short_input) values
  ('9.1.1', 1, 'mcq', 'P', $q$Trọng âm$q$, '3 phút', $q$Chọn từ có trọng âm chính rơi vào vị trí khác các từ còn lại.$q$, null, false),
  ('9.1.1', 2, 'mcq', 'R', 'Đọc hiểu — True / False', '5 phút', 'Đọc đoạn văn rồi chọn True (đúng) hoặc False (sai).', $q$<p>Bat Trang is a traditional pottery village near Ha Noi. For hundreds of years, local artisans have made beautiful pots, vases and bowls there.</p><p>Today many tourists visit the village to watch the craftsmen at work. Visitors can also try making their own pottery. The villagers have set up workshops to teach them.</p><p>Thanks to tourism, the village has developed, but some people worry about pollution from the kilns. The local authority is looking for ways to protect the environment.</p>$q$, false),
  ('9.1.1', 3, 'mcq', 'C', 'Điền vào đoạn văn', '5 phút', 'Đọc đoạn văn và chọn từ đúng cho mỗi chỗ trống (1)–(5).', $q$<p>Our neighbourhood has a lot of useful <b>(1)</b> ________ such as a library, a sports centre and a market. Last month, the community centre <b>(2)</b> ________ a clean-up day.</p><p>Many young people <b>(3)</b> ________ up for it. We picked <b>(4)</b> ________ rubbish along the river. Now I know what <b>(5)</b> ________ to keep our area clean.</p>$q$, false),
  ('9.1.1', 4, 'match', 'N', 'Nối', '4 phút', $q$Nối mỗi cụm động từ với nghĩa phù hợp.$q$, null, false),
  ('9.1.1', 5, 'error', 'E', 'Tìm lỗi sai', '4 phút', 'Chọn phần gạch chân A, B, C hoặc D bị sai trong mỗi câu.', null, false),
  ('9.1.1', 6, 'typed', 'W', 'Dạng đúng của từ', '4 phút', 'Viết dạng đúng của từ trong ngoặc. Chỉ gõ từ cần điền.', null, true),
  ('9.1.1', 7, 'typed', 'T', 'Viết lại câu', '5 phút', 'Viết lại cả câu sao cho nghĩa không đổi, bắt đầu bằng phần cho sẵn.', null, false);
