-- Seed: one practice lesson per grade 6–9 ("Luyện đề 1", after Unit 1), built on the THCS exam formats:
-- pronunciation / stress, reading True–False with a passage, gap-fill passage, matching, error identification,
-- word form and sentence transformation. Ids "<grade>.1.1" sit between Unit 1 (position 10) and teacher lessons.
-- Not given to any class: teachers give it with "Giao cho lớp".

-- Lớp 6 ---------------------------------------------------------------
select '6.1.1', p.id, 15, 'Luyện đề 1', $q$Luyện đề Unit 1 — My New School$q$,
  'Phát âm, đọc hiểu, điền đoạn văn, nối, tìm lỗi sai, dạng đúng của từ, viết lại câu',
  $q$Luyện đề 1 — My New School (dạng bài kiểm tra)$q$, 'Lớp 6 · Global Success · 30 phút'
from public.phases p where p.course_id = 'lop-6' and p.position = 10;


